		"cat.p.feeder2": "Xiaomi Smart Pet Food Feeder 2",
		"cat.p.feeder2.desc": "Кормушка xiaomi.feeder.iv2001 через Xiaomi Miot: выдача корма, план кормлений, корм в миске и в бункере, осушитель, журнал. Карточка с кошкой.",
		"cat.p.fountain2": "Xiaomi Smart Pet Fountain 2",
		"cat.p.fountain2.desc": "Поилка xiaomi.pet_waterer.iv02: насос, «нет воды», ресурс фильтра, режим. Показывается своей карточкой в комнате.",
		"cat.p.kettle2pro": "Xiaomi Smart Kettle 2 Pro",
		"cat.p.kettle2pro.desc": "Чайник xiaomi.kettle.v20 как в Mi Home: кипячение, нагрев до нужной температуры, поддержание тепла, снят ли с базы.",
		"cat.p.airfryer55": "Xiaomi Smart Air Fryer 5.5L",
		"cat.p.airfryer55.desc": "Аэрогриль xiaomi.fryer.maf07d как в Mi Home: режимы, температура и время, старт, пауза, отмена, подогрев.",
		"cat.p.sarosZ70": "Roborock Saros Z70",
		"cat.p.sarosZ70.desc": "Робот-пылесос roborock.vacuum.a179 с док-станцией: уборка по комнатам, карта, расходники, режимы. Своя карточка и панель уборки.",
		"cat.p.aqaraG4": "Aqara Video Doorbell G4",
		"cat.p.aqaraG4.desc": "Видеозвонок SVD-C02 через HomeKit: звонок на весь экран на всех устройствах, видео, движение, батарея.",
		"cat.p.imouRanger": "Imou Ranger 2C",
		"cat.p.imouRanger.desc": "Камера IPC-K2EC: видео из домашней сети, шторка приватности, поворот, пресеты, обнаружение людей и питомцев через облако Imou.",
		"cat.p.camC44": "SONOFF CAM-C44HE",
		"cat.p.camC44.desc": "Камера с двумя объективами по ONVIF: видео, события «человек», «питомец», «машина», «движение», поворот.",
		"cat.p.c700": "Xiaomi Smart Camera C700",
		"cat.p.c700.desc": "Камера chuangmi.camera через go2rtc и Xiaomi Miot: живое видео, питание, обнаружение движения, ночной режим, запись.",
		"cat.p.nitromix": "Demir Döküm Nitromix P24",
		"cat.p.nitromix.desc": "Котёл по шине eBUS (ebusd через MQTT): подача и обратка, давление, пламя, горячая вода, предупреждение о низком давлении.",
		"cat.p.air": "Воздух в доме",
		"cat.p.air.desc": "Сводка воздуха по комнатам: температура, влажность, CO₂, PM2.5, худшая комната и кнопки «убрать влагу» и «очистить воздух». Нужен хотя бы один датчик CO₂ или PM2.5.",
		"cat.p.clock": "Часы, будильники и таймеры",
		"cat.p.clock.desc": "Часы дома с погодой, будильники и до трёх таймеров с сигналом на всех устройствах.",
		"cat.r.pump": "Насос",
		"cat.r.waterLow": "Мало воды",
		"cat.r.mode2": "Режим",
		"cat.r.vacuum": "Робот-пылесос",
		"cat.r.battery": "Батарея",
		"cat.r.map": "Карта",
		"cat.selfPlaced": "Эта карточка сама встаёт на своё место: на главную, в комнату прибора или в свой раздел. Здесь указываются только её сущности.",
		"cat.selfPages": "Ниже её можно поставить ещё и на страницу панели.",
		"cat.moduleTaken": "Такая карточка в доме уже есть. Откройте её, чтобы поменять сущности.",
		"cat.moduleOtherDevice": "Эта карточка пока работает с одним прибором такой модели — с тем, что найден первым. Выберите его.",
		"cat.optBad": "Только латинские буквы, цифры, «_», «.» и «-», до 64 знаков: {list}."
